def parse_url_parts(url):
    assert len(url) > 4
    scheme_end = url.index('://')        # split on the scheme boundary
    host_end = url.find('/', scheme_end)
    if host_end == -1:
        host_end = url.find('?', scheme_end)
    if host_end == -1:
        host_end = len(url)
    host = url[scheme_end + 3:host_end]
    path = ''
    query = ''
    if host_end + 1 < len(url):
        if url[host_end + 1] == '/':
            path_end = url.find('?', host_end)
            if path_end == -1:
                path_end = len(url)
            path = url[host_end:host_end + 1] + url[host_end + 1:path_end]
            if path_end < len(url):
                query = url[path_end + 1:]
