            if item in cart:
                old_qty, price = cart[item]
                if old_qty <= qty:
                    del cart[item]
                else:
                    cart[item] = (old_qty - qty, price)
        elif action[0] == 'clear':
            cart.clear()
    return sum(qty * price for qty, price in cart.values())
