def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    if requests:
        if direction == 1:
            first = start_floor
            while first <= top_floor:
                if first in requests:
                    yield first
                first += 1
        else:  # direction == -1
            first = start_floor
