def point_in_triangle(p, a, b, c):
    from itertools import permutations

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
    x, y = p
    t = [(a, b, c), (a, c, b), (b, c, a)]
