def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    if red_duration == 0 or green_duration == 0:
        return []
    period = red_duration + green_duration
    red_ticks = range(0, red_duration, 1)
    coinciding = [t for t in red_ticks if t in arrivals]
    if arrivals and arrivals[0] in red_ticks:
        first = arrivals[0]
    elif arrivals:
        first = arrivals[0] + period - green_duration
    else:
        return []
    for t in red_ticks:
        first = max(first, t)
    crossings = [first]
    for a in arrivals[1:]:
        if a in red_ticks or a in coinciding:
            crossings.append(a)
        else:
            crossings.append(a + (period - green_duration))
    return crossings
