def is_point_on_segment(p, a, b):
    from fractions import Fraction
    x, y = p
    ax, ay = a
    bx, by = b
    if ax == bx and ay == by:
        # a and b are the same point; p must be equal to either to qualify
        return p == (ax, ay)
    # Tolerate all floating point components
    def equals(u, v):
        return Fraction(u).limit_denominator(1000000) == Fraction(v).limit_denominator(1000000)
    # Check whether p lies on the infinite line through a and b
    # Zero area tells us it lies on the line
    cross = (bx - ax) * (y - ay) - (by - ay) * (x - ax)
    if not equals(cross, 0):
        return False
    # Check that p also lies between a and b, inclusive of the endpoints
    if not (equals(min(ax, bx), x) and equals(max(ax, bx), x)):
        return False
    if not (equals(min(ay, by), y) and equals(max(ay, by), y)):
        return False
    return True
```

